<script setup lang="ts">
import { onMounted,ref } from "vue";import { useRoute,useRouter } from "vue-router";import { getLiveReport,REPORT_STATUS_LABEL,type LiveReport } from "@/api/liveReport";import { getMaterialFileIcon } from "@/views/settings/materials/materialFileIcons";import UiButton from "@/components/ui/UiButton.vue";import ReportAuditDrawer from "./ReportAuditDrawer.vue";
const route=useRoute(),router=useRouter(),data=ref<LiveReport>(),loading=ref(false),error=ref(""),audits=ref(route.query.audits==="1");async function load(){loading.value=true;try{data.value=await getLiveReport(String(route.params.id));}catch(e){error.value=e instanceof Error?e.message:"加载失败";}finally{loading.value=false;}}onMounted(load);
</script>
<template><div class="page"><div class="crumb">直播 / 直播报备 / 查看详情</div><div v-loading="loading" class="card"><p v-if="error" class="err">{{error}}</p><template v-if="data"><header><h2>{{data.title}}</h2><span :class="data.status">{{REPORT_STATUS_LABEL[data.status]}}</span><div><UiButton v-if="data.status==='pending'" variant="primary" @click="router.push(`/live-reports/${data.id}/audit`)">去审核</UiButton><UiButton v-if="data.status==='rejected'||(data.status==='passed'&&!data.boundLiveCount)" @click="router.push(`/live-reports/${data.id}/edit`)">编辑</UiButton><UiButton @click="audits=true">审核记录</UiButton></div></header><dl><dt>报备直播名称</dt><dd>{{data.title}}</dd><dt>直播报备内容</dt><dd>{{data.content}}</dd><dt>计划时间</dt><dd><p v-for="(x,i) in data.planTimes" :key="i">{{x.startTime}} 至 {{x.endTime}}</p></dd><dt>报备直播封面</dt><dd><img class="cover" :src="data.coverUrl" alt=""></dd><dt>主播</dt><dd>{{data.host.userName}}</dd><dt>直播报备材料</dt><dd><div v-for="f in data.attachments" :key="f.objectKey" class="file"><img :src="getMaterialFileIcon(f.name)" class="file-icon" alt=""><b>{{f.name}}</b><span>{{(f.fileSize/1024/1024).toFixed(2)}}MB</span><a :href="f.url" target="_blank">预览</a><a :href="f.url" :download="f.name">下载</a></div></dd></dl><footer><span>提交人 {{data.submitterName}}</span><span>所属部门 {{data.departmentName||'--'}}</span><span>提交时间 {{data.submittedAt}}</span></footer><ReportAuditDrawer v-model="audits" :report-id="data.id" :title="data.title" /></template></div></div></template>
<style scoped>.page{min-width:800px}.crumb{margin-bottom:12px;color:#666;font-size:13px}.card{background:#fff;border-radius:6px;min-height:500px;padding:18px 24px}.err{color:var(--color-danger)}header{display:flex;align-items:center;gap:12px;border-bottom:1px solid #eee;padding-bottom:16px}header h2{margin:0;font-size:17px}header>div{margin-left:auto;display:flex;gap:8px}header>span{padding:2px 7px;background:#f5f5f5}.passed{color:#389e0d;background:#f6ffed}.rejected{color:#cf1322;background:#fff1f0}dl{display:grid;grid-template-columns:130px 1fr;gap:20px 16px;padding:12px 0}dt{text-align:right;color:#666;font-size:13px}dd{margin:0;font-size:13px;line-height:1.6}dd p{margin:0 0 5px}.cover{width:160px;height:100px;object-fit:cover}.file{display:grid;grid-template-columns:28px minmax(180px,300px) 70px auto auto;align-items:center;gap:10px;background:#f7f8fa;padding:10px 12px;width:max-content;min-width:470px}.file-icon{width:28px;height:28px;object-fit:contain}.file a{color:var(--color-primary);text-decoration:none}footer{display:flex;justify-content:space-between;border-top:1px solid #eee;padding:18px;color:#666;font-size:12px}</style>
